@module generators  src=generators.lua  loc=636  mode=namespace  self=generators

# Invariants & contracts
  @invariant  pure module, no state; a stage is fn(stream, host, params, ctx) -> { notes, delta }  @ 7
  @invariant  stream and host share one shape; stages read stream, host is the untouched original  @ 8
  @invariant  pb/ccs are absolute curves over the closed window (edge values seeded); pb val is cents  @ 10
  @invariant  ctx binds resolution, pbRangeCents, nextSameLaneNote, step(p,d,n), stepsBetween(a,b)  @ 11
  @invariant  periods are QN per the periodQN convention -- scalar or {num,den}  @ 12
  @invariant  mode is the stream fold -- replace overwrites the dest channel, augment adds to it  @ 16
  @contract  chord-stamp stamps a poly pattern on each region member; lane-1 is the pattern's root  @ 153
  @contract  rebase whole temper steps via ctx.stepsBetween+ctx.step; voice keeps trigger vel/window  @ 154
  @contract  no lane-1 note in the pattern -> inert (empty result)  @ 155
  @contract  dest is a per-entry param; registry dest is only its seed + note-vs-continuous marker  @ 432

# Shapes
  @shape  stream/host = { window={startppq,endppq}, chan, lane, id, notes={ {pitch,vel,detune,ppq,endppq},.. }, pas={ {ppq,pitch,vel},.. }, ccs={ [cc]={ {ppq,val,shape,[tension]},.. } }, ats={ {ppq,val},.. }, pb={ {ppq,val,shape,[tension]},.. } }  @ 9
  @shape  result = { notes = { {ppq,endppq,pitch,vel,detune}, ... }, delta = { {ppq,val,shape,[tension]}, ... } }  @ 13
  @shape  kinds[kind] = { expand, mode='replace'|'augment', dest='note'|'pb'|<cc>, dests?='any'|'pb'|'cc', label, glyph, defaults, fields }  @ 14
  @shape  field = { field, label, widget, base?, coarse?, min?, max?, options?, when?, kind?, poly?, quantity?='magnitude', signed?, frac? }  @ 15
  @shape  fxPatterns (ds project) = { [name] = { kind='notes'|'curve', lengthPpq, rpb=rowsPerBeat, root?=midiPitch, specs?={ {lane,ppq,endppq,pitch,vel,detune,delay,sample?},.. }, points?={ {ppq,val,shape,tension?},.. } } }  @ 19
  @shape  destProfile = { unit, rest, bipolar, magScale } -- continuous dests only ('pb' | cc number)  @ 433
  @shape  parkWindows -> { {evType='note'|'cc'|'pb', chan, cc?, id, startppq, endppq}, ... } (cc on cc windows only)  @ 559

